  /// for, keyed by JSON name, so a round trip keeps it.
  final Map<String, String> rawEnums;

  factory InboxItem.fromJson(Map<String, dynamic> json) {
    final rawEnums = <String, String>{};
    final kindWire = json['kind'] as String;
    final kind = InboxItemKind.fromWire(kindWire);
    if (kind == InboxItemKind.unknown) {
      rawEnums['kind'] = kindWire;
    }
    return InboxItem(
      kind: kind,
      agentID: json['agentId'] as String?,
      submission: _objectOrNull(
        json['submission'],
        PendingSubmission.fromJson,
      ),
      at: json['at'] as String,
      rawEnums: rawEnums,
    );
