  Map<String, dynamic> toJson() {
    final json = <String, dynamic>{};
    json['kind'] = rawEnums['kind'] ?? kind.wire;
    if (agentID != null) {
      json['agentId'] = agentID;
    }
    if (submission != null) {
      json['submission'] = submission!.toJson();
    }
    json['at'] = at;
    return json;
  }
}

